        a.hull(m,[[966,513],[1017,520],[1069,540],[1075,568],[1027,550]],-.022,.022,O.WOOD);
        a.hull(m,[[1017,521],[1068,529],[1187,573],[1237,600],[1236,627],[1202,628],[1066,577]],-.022,.026,O.WOOD);
        a.hull(m,[[1234,600],[1261,609],[1280,625],[1280,646],[1240,637]],-.022,.026,O.WOOD);
